import sys
import threading
import json
import collections

import logging
from six import get_function_code
from ta_messaging.exceptions import MessageObserverTimeout, UnsupportedVerificationCallback, FailedMessageSubscription, MessageObserverFailure
from ta_messaging.message_types_utils import _map_user_protocol_to_database_protocols, protocol_exists

if sys.version_info[0] >= 3:
    from queue import Queue, Empty
else:
    from Queue import Queue, Empty


class MessageObserver(object):
    '''
    Entity responsible for capturing desired message.

    Defines two-step message verification:

    * precondition used by dispatcher composed of message_type and message_owner
    * optional verification_callback for more detailed matching
    '''

    def __init__(self, publisher, protocol, message_type, owner, timeout, verification_callback):
        '''
        :param publisher: where observer subscribes for messages
        :param protocol: subscription is for this protocol
        :param message_type: subscription is for this type
        :param owner: and for this owner (means messages of this owner)
        :param timeout: when to give up
        :param verification_callback: function returning boolean

        verification_callback has to be function of following pattern::

            def is_my_msg(parsed_message):
                try:
                    value = parsed_message.get_value_by_unique_key('field_name')
                except NotFoundKey, AmbiguousKey:
                    return False
                return True if value == self.expected_value else False

        or if verdict is not based on message content
        just provide parameterless function::

            def is_second_occurrence_of_msg():
                self.current_occurrence += 1
                return True if self.current_occurrence  == self.awaited_occurrence else False
        '''
        self._protocol = protocol
        self._protocol_source_aligned = _map_user_protocol_to_database_protocols(self._protocol)
        self._message_type = message_type
        self._owner = owner
        self.logger = logging.getLogger('messaging.flows')
        self.logger_msgs = logging.getLogger('messaging.flows.logic')
        self._protocol_logged_once = False
        MessageObserver._validate_callback_format(verification_callback)
        self._verification_callback = verification_callback
        if self._verification_callback is None:
            self._verification_callback_name = ""
        elif hasattr(self._verification_callback, '__query__'):
            self._verification_callback_name = self._verification_callback.__query__
        elif hasattr(self._verification_callback, '__wrapped__'):
            self._verification_callback_name = self._verification_callback.__wrapped__.__name__
        else:
            self._verification_callback_name = self._verification_callback.__name__
        self._timeout = timeout
        self._stopped_by_external_error = False
        self._publisher = publisher
        self.msg_queue = Queue()
        self._total_seen_messages = 0
        self._total_seen_messages_matching_protocol = 0
        self._last_seen_messages = collections.deque(maxlen=5)  # we remember only last 5 msgs
        self._desired_msg = None
        self._timeouted = False
        self._observer_exception = None
        self.is_running = threading.Event()
        self.is_running.set()
        self._started = threading.Semaphore(0)
        self._ended = threading.Semaphore(0)
        self._timer = threading.Timer(self._timeout, self._on_timeout)
        self._start_in_separate_thread()
        self._started.acquire()
        self.logger.debug('%r started' % self)

    def __repr__(self):
        class_name = self.__class__.__name__
        queue_name = 'Que:{}'.format(hex(id(self.msg_queue)))  # important in debugs since it is used for subscriptions
        return '%s(%s of %s, %s)' % (class_name, self._message_type, self._owner, queue_name)

    def __str__(self):
        class_name = self.__class__.__name__
        if 'alias' in self._owner:
            return '%s(%s:%s)' % (class_name, self._owner['alias'], self._message_type)
        return '%s(%s of %s)' % (class_name, self._message_type, self._owner)

    def get_message(self):
        '''
        Returns message that is fulfilling observer condition.

        If get_message is called during runtime it awaits observer finish.

        :return: Message instance
        :raises MessageObserverTimeout: if message is not captured before timeout
        '''
        self._wait_for_message_or_raise_exception_on_timeout()
        parsed_message = self._create_message_from_unparsed_form(self._desired_msg)
        pprinted_msg = json.dumps(parsed_message, indent=2)
        self.logger_msgs.debug('%s returning parsed message: %s' % (self, pprinted_msg))
        return parsed_message

    def verify_message_has_been_caught(self):
        '''
        Checks if message is successfully captured

        :return: None: if message is successfully captured
        :raises MessageObserverTimeout: if message is not captured before timeout
        '''
        self._wait_for_message_or_raise_exception_on_timeout()
        return

    def subscribe(self):
        '''
        Subscribe itself to publisher.

        From now on publisher will be sending messages to this observer if condition (message type and owner) will be met.
        '''
        try:
            self._publisher.subscribe_observer(self.msg_queue, self._message_type, self._owner, self.is_running)
            self.logger.debug('%r has been subscribed at %s for message %s' % (self, self._publisher, self._message_type))
        except Exception as exc:
            self.logger.debug('%r failed to subscribe at %s for message %s' % (self, self._publisher, self._message_type))
            raise FailedMessageSubscription(exc, self._message_type, self._owner)

    def unsubscribe(self):
        '''
        Unsubscribes itself from publisher.
        From now on publisher will not be sending messages to this observer.
        :return: None
        '''
        self._publisher.unsubscribe_observer(self.msg_queue)
        self.logger.debug('%r unsubscribed from %s' % (self, self._publisher))

    def stop(self):
        '''
        Terminates observer loop and cleans up
        '''
        if self.is_running.is_set():
            self.is_running.clear()
            self._ended.acquire()

    def start(self):
        '''
        Starts observer loop, subscribes to dispatcher and awaits for expected message.
        '''
        self.logger.debug('{!r} thread started'.format(self))
        self.is_running.set()
        self._timer.start()
        try:
            self.subscribe()
            self._enter_observer_loop()

        except Exception as exc:
            self._observer_exception = exc
        finally:
            self._started.release()
            self.is_running.clear()
            try:
                self.unsubscribe()
            except Exception:
                pass

            self._log_based_on_observer_result()
            # added to mark done any message that was fed into queue when observer already timeout
            try:
                self.msg_queue.task_done()
            except ValueError:
                pass
        self._timer.cancel()
        self._ended.release()
        self.logger.debug('{!r} thread finished'.format(self))

    def _log_based_on_observer_result(self):
        if self._stopped_by_external_error is True:
            self.logger_msgs.debug('%r stopped by other fails awaiting for message %s ' % (self, self._message_type))
        elif not self._timeouted:
            self.logger_msgs.debug('%s successfully caught %s' % (self, self._message_type))
        else:
            self.logger_msgs.debug('%s timeout on %s, trying to release any message waiting for consumption' % (self, self._message_type))

    def _enter_observer_loop(self):
        '''
        Starts observer loop
        '''
        self._started.release()
        while self.is_running.is_set():
            try:
                unparsed_msg = self.msg_queue.get(timeout=0.01)
                self.logger.debug('%r got %s from publisher' % (self, unparsed_msg))
            except Empty:
                continue
            self._total_seen_messages += 1
            self._last_seen_messages.append(unparsed_msg)
            if self._is_expected_message(unparsed_msg):
                self.logger.debug('%s accepted message %s' % (self, unparsed_msg.message_type))
                self._on_success(unparsed_msg)
            else:
                self.msg_queue.task_done()

    def _on_success(self, msg):
        if self._timeouted is False:
            self._timer.cancel()
            self._desired_msg = msg
            self.is_running.clear()

    def _on_timeout(self):
        if self._desired_msg is None:
            self._timeouted = True
            self.is_running.clear()
            self.logger_msgs.debug('%r timeouted awaiting for message %s ' % (self, self._message_type))

    def _on_stop(self):
        self._stopped_by_external_error = True
        self.is_running.clear()
        self.logger_msgs.debug('%r stopped by other fails awaiting for message %s ' % (self, self._message_type))

    def _is_protocol_matching(self, unparsed_msg):
        """
        Check if source supports protocols extraction, if yes, compare message and observer protocols
        """
        if unparsed_msg.protocol is not None:
            if unparsed_msg.protocol == self._protocol_source_aligned:
                if not self._protocol_logged_once:
                    self.logger_msgs.debug("%r accepted message %s with protocol %s, continue to verifier part" %
                                           (self, unparsed_msg, unparsed_msg.protocol))
                    self._protocol_logged_once = True
                return True
            else:
                if not self._protocol_logged_once:
                    self.logger_msgs.debug("%r rejected message %s with protocol %s, observer protocol %s" %
                                           (self, unparsed_msg, unparsed_msg.protocol, self._protocol_source_aligned))
                    self._protocol_logged_once = True
                return False
        else:
            # this is for legacy, not protocol-supporting sources
            if not self._protocol_logged_once:
                self.logger_msgs.debug("%r accepted message %s without protocol comparision, continue to verifier part" %
                                       (self, unparsed_msg))
                self._protocol_logged_once = True
            return True

    def _is_expected_message(self, unparsed_msg):  # Inheritance API
        '''
        Decides whether given message is the one expected or not

        This is the only method expected to be overwritten by derived observer class

        :param unparsed_msg: object of Message type
        :return: information if given message is expected or not
        :raises UnsupportedVerificationCallback: if number of arguments for msg is not supported
        '''
        if self._is_protocol_matching(unparsed_msg) is False:
            return False
        self._total_seen_messages_matching_protocol += 1
        if get_function_code(self._verification_callback.__wrapped__).co_argcount == 0:
            # if callback is not registered with decorator, it has no __wrapped__ set
            is_expected = self._verification_callback()
            if not is_expected:
                self.logger_msgs.debug("%r rejected message %s due to verifier result" % (self, unparsed_msg))
            return is_expected
        else:  # must be 1 - see: _validate_callback_format()
            is_expected = self._verification_callback(unparsed_msg)
            if is_expected:
                pprinted_msg = json.dumps(unparsed_msg.parse(), indent=2)
                self.logger_msgs.debug('%s using filter "%s" caught message with following details:\n%s' % (self, self._verification_callback_name,
                                                                                                            pprinted_msg))
            else:
                verifier_name = self._verification_callback_name
                self.logger.debug("'%r rejected message %s due to '%s(message)' filter result" % (self, unparsed_msg, verifier_name))
            return is_expected

    def _wait_for_message(self):
        if self.is_running.is_set():
            self._ended.acquire()

    def _wait_for_message_or_raise_exception_on_timeout(self):
        self._wait_for_message()
        if self._observer_exception:
            raise MessageObserverFailure(self._observer_exception, self._message_type, self._owner)
        if self._timeouted:
            raise MessageObserverTimeout(message_type=self._message_type,
                                         owner=self._owner,
                                         total_seen_messages=self._total_seen_messages,
                                         total_seen_messages_matching_protocol=self._total_seen_messages_matching_protocol,
                                         last_seen_messages=list(self._last_seen_messages),  # want copy
                                         validator=self._verification_callback_name)

    def _create_message_from_unparsed_form(self, unparsed_message):
        return unparsed_message.parse()

    @staticmethod
    def _validate_callback_format(verification_callback):
        if verification_callback:
            func_arg_count = get_function_code(verification_callback.__wrapped__).co_argcount
            if func_arg_count <= 1 or (func_arg_count == 2 and 'self' in
                                       get_function_code(verification_callback.__wrapped__).co_varnames):
                pass
            else:
                raise UnsupportedVerificationCallback('Wrong number of verification_callback parameters: {} '
                                                      '(should be 0 or 1 or 2(for self functions)'
                                                      .format(get_function_code(verification_callback).co_argcount))

    def _start_in_separate_thread(self):
        threading.Thread(target=self.start).start()


class InfiniteCallbackObserver(MessageObserver):
    """
       Entity responsible for continuous capturing desired message.
       On every message it triggers user given callback with message as argument.
       Not designed to be used by MessageFlow class.
       The instance must be stopped via invoking stop() method.
    """
    def __init__(self, publisher, message_type, owner, callback, protocol=None):
        """
            :param publisher: where observer subscribes for messages
            :param message_type: subscription is for this type
            :param owner: and for this owner (means messages of this owner)
            :param callback:  user defined callback executed on every message occurrence
            :param protocol: optional protol filtering may be applied

            verification_callback has to be function of following pattern::

                def is_my_msg(parsed_message):
                    try:
                        value = parsed_message.get_value_by_unique_key('field_name')
                    except NotFoundKey, AmbiguousKey:
                        return False
                    return True if value == self.expected_value else False

            or if verdict is not based on message content
            just provide parameterless function::

                def is_second_occurrence_of_msg():
                    self.current_occurrence += 1
                    return True if self.current_occurrence  == self.awaited_occurrence else False
        """
        if protocol is not None and protocol_exists(protocol):
            self._protocol = protocol
            self._protocol_source_aligned = _map_user_protocol_to_database_protocols(protocol)
        else:
            self._protocol = protocol
        self._message_type = message_type
        self._owner = owner
        self.logger = logging.getLogger('messaging.flows')
        MessageObserver._validate_callback_format(callback)
        self._callback = callback
        self._publisher = publisher
        self.msg_queue = Queue()
        self._observer_exception = None
        self.is_running = threading.Event()
        self._ended = threading.Semaphore(0)
        self._started = threading.Semaphore(0)
        self._start_in_separate_thread()
        self._started.acquire()
        self.logger.debug('%r started' % self)

    def start(self):
        """
        Starts observer loop, subscribes to dispatcher and awaits for expected message.
        """
        self.logger.debug('{!r} infinite thread started'.format(self))
        self.is_running.set()
        try:
            self.subscribe()
            self._enter_observer_loop()

        except Exception as exc:
            self._observer_exception = exc
        finally:
            self.is_running.clear()
            self._started.release()
            try:
                self.unsubscribe()
            except Exception:
                pass
                self.logger.debug('%s successfully ended infinite observer for %s' % (self, self._message_type))
        self._ended.release()
        self.logger.debug('{!r} infinite thread finished'.format(self))

    def _enter_observer_loop(self):
        """
        Starts observer loop
        """
        self._started.release()
        while self.is_running.is_set():
            try:
                unparsed_msg = self.msg_queue.get(timeout=0.01)
                self.logger.debug('%r got %s from publisher' % (self, unparsed_msg))
                if self._protocol is not None:
                    if self._is_protocol_matching(unparsed_msg) is False:
                        continue
            except Empty:
                continue
            if self._callback is not None:
                self._callback(self._create_message_from_unparsed_form(unparsed_msg))
                self.logger.debug('%s callback run on message %s' % (self, unparsed_msg.message_type))


def get_occurrence_matcher(awaited_occurrence_number):
    '''
    Factory method that generates callable occurrence_matcher.

    :param occurrence_number: target number of calls
    :return: _occurrence_matcher
    '''
    current_occurrence = [0]  # must be list to not create local variable inside following function

    def _occurrence_matcher():
        current_occurrence[0] += 1
        return current_occurrence[0] == awaited_occurrence_number
    return _occurrence_matcher
